ency'' ELSE cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->''payer''->>''currency'' END as \"Issuer Currency Code\", CASE WHEN jsonb_typeof(cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)) = ''array'' THEN cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->0->''txn''->''attribs''->''pismo_raw''->''fields''->''original_network_data''->>''f37_retrieval_reference_number'' ELSE cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->''txn''->''attribs''->''pismo_raw''->''fields''->''original_network_data''->>''f37_retrieval_reference_number'' END as \"Retrieval Reference Number\", CASE WHEN jsonb_typeof(cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)) = ''array'' THEN cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->0->''txn''->>''id'' ELSE cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->''txn''->>''id'' END as \"Transaction ID\", CASE WHEN  closedby.user_id_ is not null THEN closedby.user_id_ ELSE ''Auto Closed'' END as \"Statused By User ID\", CASE WHEN  closedby.user_id_ is not null THEN userinfo.first_ ||'' '' || userinfo.last_ ELSE ''Auto Closed'' END as \"Agent Name\", hiproinst.end_time_  as  \"Alert Status change Timestamp (Asia/Calcutta)\", CASE when actionvar.text_ = ''Value_Update_Whitelist'' THEN ''Update Whitelist'' when actionvar.text_ = ''Value_Fraud'' THEN ''Report Fraud to CRM'' when actionvar.text_ = ''Value_Close'' THEN ''False Positive, Close Case'' END as \"Action taken or status\", triggeredtype.text_ as \"Rule type\", replace(replace(replace(rulename.text_, ''['', ''''), '']'',''''),''\"'','''') as \"Rule Name\" from camunda.act_hi_procinst hiproinst full outer join camunda.act_hi_varinst actionvar on actionvar.proc_inst_id_ = hiproinst.proc_inst_id_ and actionvar.name_ = ''Action'' full outer join camunda.act_hi_op_log closedby on closedby.id_ = (select id_ from camunda.act_hi_op_log where proc_inst_id_ = hiproinst.proc_inst_id_ and operation_type_ = ''Complete'' and entity_type_ = ''Task'' and property_ = ''delete'' 