      "CreatedOn":"select CASE WHEN jsonb_typeof(cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)) =''array'' then cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->0->''txn''->>''class'' else cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->''txn''->>''class'' END as \"Class (CUB or USFB)\", accountid.long_ as \"Account ID\", null as \"Document Number\", CASE WHEN jsonb_typeof(cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)) =''array'' then cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->0->''txn''->''attribs''->''pismo_raw''->''fields''->>''last_four_digits'' else  cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->''txn''->''attribs''->''pismo_raw''->''fields''->>''last_four_digits'' END  as \"Last 4 digits of card\", CASE WHEN jsonb_typeof(cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)) =''array'' then cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->0->''observations''->''payerVPA''->>''vpaName'' else  cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->''observations''->''payerVPA''->>''vpaName'' END  as \"Customer Name\", TransactionAmount.double_ / 100 as \"Transaction Amount\", CASE WHEN jsonb_typeof(cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)) =''array'' then cast(cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->0->''txn''->>''ts'' as timestamp) at time zone ''Asia/Kolkata'' at time zone  :timeZone else cast(cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->''txn''->>''ts'' as timestamp) at time zone ''Asia/Kolkata'' at time zone  :timeZone END  as \"Authorization Timestamp\", riskscore.long_ as \"Advanced Authorization Risk Score\", null as \"Authorization Response Code\", triggeredtype.text_ as \"Approved/Declined\", CASE WHEN jsonb_typeof(cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)) =''array'' then cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->0->''txn''->''attribs''->>''pos_entry_mode'' else cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->''txn''->''attribs''->>''pos_entry_mode'' END  as \"POS Entry Mode\", CASE WHEN jsonb_typeof(cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)) =''array'' then cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->0->''payee''->>''mcc'' else cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->''payee''->>''mcc'' END  as \"Merchant Category Code (MCC)\", CASE WHEN jsonb_typeof(cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)) = ''array'' THEN cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->0->''payeeVPA''->>''vpaName'' ELSE cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->''observations''->''payeeVPA''->>''vpaName'' END as \"Merchant Name\", CASE WHEN jsonb_typeof(cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)) = ''array'' THEN cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->0->''txn''->''attribs''->''pismo_raw''->''fields''->>''merchant_state_or_country_code'' ELSE cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->''txn''->''attribs''->''pismo_raw''->''fields''->>''merchant_state_or_country_code'' END as \"Merchant Location\", CASE WHEN jsonb_typeof(cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)) = ''array'' THEN cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->0->''txn''->''attribs''->''pismo_raw''->''fields''->>''merchant_state_or_country_code'' ELSE cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->''txn''->''attribs''->''pismo_raw''->''fields''->>''merchant_state_or_country_code'' END as \"Card Acceptor Country Code\", null as \"Acquirer Country Code\", CASE WHEN jsonb_typeof(cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)) = ''array'' THEN cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->0->''txn''->''attribs''->>''moto_eci_recurring'' ELSE cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->''txn''->''attribs''->>''moto_eci_recurring'' END as \"MOTO/ECI/Recurring\", CASE WHEN jsonb_typeof(cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)) = ''array'' THEN cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->0->''payer''->>''currency'' ELSE cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->''payer''->>''currency'' END as \"Issuer Currency Code\", CASE WHEN jsonb_typeof(cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)) = ''array'' THEN cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->0->''txn''->''attribs''->''pismo_raw''->''fields''->''original_network_data''->>''f37_retrieval_reference_number'' ELSE cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->''txn''->''attribs''->''pismo_raw''->''fields''->''original_network_data''->>''f37_retrieval_reference_number'' END as \"Retrieval Reference Number\", CASE WHEN jsonb_typeof(cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)) = ''array'' THEN cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->0->''txn''->>''id'' ELSE cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->''txn''->>''id'' END as \"Transaction ID\", CASE WHEN  closedby.user_id_ is not null THEN closedby.user_id_ ELSE ''Auto Closed'' END as \"Statused By User ID\", CASE WHEN  closedby.user_id_ is not null THEN userinfo.first_ ||'' '' || userinfo.last_ ELSE ''Auto Closed'' END as \"Agent Name\", hiproinst.end_time_  as  \"Alert Status change Timestamp (Asia/Calcutta)\", CASE when actionvar.text_ = ''Value_Update_Whitelist'' THEN ''Update Whitelist'' when actionvar.text_ = ''Value_Fraud'' THEN ''Report Fraud to CRM'' when actionvar.text_ = ''Value_Close'' THEN ''False Positive, Close Case'' END as \"Action taken or status\", triggeredtype.text_ as \"Rule type\", replace(replace(replace(rulename.text_, ''['', ''''), '']'',''''),''\"'','''') as \"Rule Name\" from camunda.act_hi_procinst hiproinst full outer join camunda.act_hi_varinst actionvar on actionvar.proc_inst_id_ = hiproinst.proc_inst_id_ and actionvar.name_ = ''Action'' full outer join camunda.act_hi_op_log closedby on closedby.id_ = (select id_ from camunda.act_hi_op_log where proc_inst_id_ = hiproinst.proc_inst_id_ and operation_type_ = ''Complete'' and entity_type_ = ''Task'' and property_ = ''delete'' order by timestamp_ desc limit 1) full outer join camunda.act_hi_varinst accountid on accountid.proc_inst_id_ = hiproinst.proc_inst_id_ and accountid.name_ = ''accountid'' full outer join camunda.act_hi_varinst riskscore on riskscore.proc_inst_id_ = hiproinst.proc_inst_id_ and riskscore.name_ = ''RiskScore'' full outer join camunda.act_hi_varinst  TransactionAmount on TransactionAmount.proc_inst_id_ = hiproinst.proc_inst_id_ and TransactionAmount.name_ = ''TransactionAmount'' full outer join camunda.act_hi_varinst triggeredtype  on triggeredtype.proc_inst_id_ = hiproinst.proc_inst_id_ and triggeredtype.name_ = ''triggeredtype'' full outer join camunda.act_hi_varinst  Txn on Txn.proc_inst_id_ = hiproinst.proc_inst_id_ and Txn.name_ = ''Transaction'' full outer join camunda.act_ge_bytearray Txnorg on Txnorg.id_ = Txn.bytearray_id_ full outer join camunda.act_hi_varinst rulename on rulename.proc_inst_id_ = hiproinst.proc_inst_id_ and rulename.name_ = ''failedRules'' full outer join camunda.act_id_user userinfo on userinfo.id_ = closedby.user_id_ where cast(hiproinst.start_time_ as date) between cast(:StartDate as date) and cast(:EndDate as date)-1 and hiproinst.state_ = ''COMPLETED'' and hiproinst.proc_def_key_ not in ( ''invoice'', ''ReviewInvoice'',''Orchestrator'', ''Sanctions'') and hiproinst.proc_def_key_ = :CaseType"
    }
  }'::text WHERE
idashboardqueryid = 73;


