UPDATE ui.dashboardquery SET
vcdashboardquery = 'SELECT r.vcdecisionname as "Decision Name", r.vcdecisiondetail as "Decision Description", r.idecisionid as "Decision ID", makeruser.vcusername as "Maker User", r.dtentrystamp at time zone ''asia/kolkata'' as "Maker Time Stamp", r.vcremark as "Maker & Checker Remarks", checkeruser.vcusername as "Checker User", r.dtapproverstamp at time zone ''asia/kolkata'' as "Checker Time Stamp", case when r.vcaction = ''A'' then ''Add'' when r.vcaction = ''M'' then ''Modify'' when r.vcaction = ''X'' then ''Delete'' when r.vcaction = ''N'' then ''No Change'' end as "Action", cast(r.vcresultparams as text) as "Decision Parameters", p.vcproductname as "Product Name", cast(r.attribs as text) as "Attributes", r.vcdecisionmapinfo as "Decision Info" FROM ui.decisionsworkflowaudit r left join masters.products p on r.iproductid = p.iproductid left join ui.webuser makeruser on makeruser.iuserid = r.ientryuserid left join ui.webuser checkeruser on checkeruser.iuserid = r.iapproveruserid where cast(r.dtentrystamp at time zone :timeZone as date) between cast(:StartDate as date) and cast(:EndDate as date)-1;'::text WHERE
idashboardqueryid = 84;


UPDATE ui.dashboardquery SET
vcdashboardquery = 'SELECT r.vccolumnname as "Parameter Name", r.vcdescription as  "Parameter Description", r.vcdtype as "Data Type", cast(r.vcprefix as text) as "Prefix", r.vcpath as "Path", r.vcroot as "Root Level", r.bml as "ML", r.bscore as "Score", r.bui as "UI", cast(r.config as text) as "Config", makeruser.vcusername as "Maker User", r.dtentrystamp at time zone ''asia/kolkata'' as "Maker Time Stamp", r.vcremark as "Maker & Checker Remarks", checkeruser.vcusername as "Checker User", r.dtapproverstamp at time zone ''asia/kolkata'' as "Checker Time Stamp", case when r.vcaction = ''A'' then ''Add'' when r.vcaction = ''M'' then ''Modify'' when r.vcaction = ''X'' then ''Delete'' when r.vcaction = ''N'' then ''No Change'' end as "Action" FROM ui.metadataaudit r left join ui.webuser makeruser on makeruser.iuserid = r.ientryuserid left join ui.webuser checkeruser on checkeruser.iuserid = r.iapproveruserid where cast(r.dtentrystamp at time zone :timeZone as date) between cast(:StartDate as date) and cast(:EndDate as date)-1;'::text WHERE
idashboardqueryid = 88;


